409	      );
410	      if (this.session.sheet() !== sheet) return;
411	      this.replace(saved);
412	      this.quickName.set('');
413	      this.quickAmount.set('');
414	    } catch (err) {
415	      if (this.session.sheet() !== sheet) return;
416	      const refusal = err instanceof HttpErrorResponse && err.status === 409 ? err.error?.message : undefined;
417	      this.quickError.set(refusal ?? 'Could not add the claim.');
418	    } finally {
419	      this.quickBusy = false;
420	    }
421	  }
422	
423	  /** Take a statement for the person: their counting claims are bound to the figures they have now. */
424	  protected async statement(p: Person): Promise<void> {
425	    if (this.stating) return;
426	    this.personError.set(null);
427	    this.patronError.set(null);
428	    const sheet = this.session.sheet();
429	    if (!sheet) return;
430	    const headers = { 'X-User': this.session.user() ?? '' };
431	    this.stating = true;
432	    try {
433	      const saved = await firstValueFrom(
434	        this.http.post<Person>(
435	          `/api/sheets/${encodeURIComponent(sheet)}/people/${p.id}/statement`,
436	          null,
437	          { headers },
438	        ),
439	      );
440	      if (this.session.sheet() !== sheet) return;
441	      this.replace(saved);
442	    } catch {
443	      if (this.session.sheet() !== sheet) return;
444	      this.personError.set({ id: p.id, message: 'Could not take the statement.' });
445	    } finally {
446	      this.stating = false;
447	    }
448	  }
449	
450	  /** Retire the person from a date; a date left blank takes the sheet's today. */
451	  protected async retire(p: Person, from: string): Promise<void> {
452	    if (this.retiring) return;
453	    this.personError.set(null);
454	    this.patronError.set(null);
455	    const sheet = this.session.sheet();
456	    if (!sheet) return;
457	    const date = from.trim();
458	    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
459	      this.personError.set({ id: p.id, message: 'Enter a date, or leave it blank for today.' });
460	      return;
461	    }
462	    const headers = { 'X-User': this.session.user() ?? '' };
463	    this.retiring = true;
464	    try {
465	      const saved = await firstValueFrom(
466	        this.http.post<Person>(
467	          `/api/sheets/${encodeURIComponent(sheet)}/people/${p.id}/retire`,
468	          { from: date || null },
469	          { headers },
470	        ),
471	      );
472	      if (this.session.sheet() !== sheet) return;
473	      this.replace(saved);
474	    } catch {
475	      if (this.session.sheet() !== sheet) return;
476	      this.personError.set({ id: p.id, message: 'Could not retire the person.' });
477	    } finally {
478	      this.retiring = false;
479	    }
480	  }
481	
482	  /** Put the person on hold, or release them when they are on it. */
483	  protected async hold(p: Person): Promise<void> {
484	    if (this.holding) return;
485	    this.personError.set(null);
486	    this.patronError.set(null);
487	    const sheet = this.session.sheet();
488	    if (!sheet) return;
