490	    this.holding = true;
491	    try {
492	      const saved = await firstValueFrom(
493	        this.http.post<Person>(
494	          `/api/sheets/${encodeURIComponent(sheet)}/people/${p.id}/hold`,
495	          { held: !p.held },
496	          { headers },
497	        ),
498	      );
499	      if (this.session.sheet() !== sheet) return;
500	      this.replace(saved);
501	    } catch {
502	      if (this.session.sheet() !== sheet) return;
503	      this.personError.set({ id: p.id, message: p.held ? 'Could not release the person.' : 'Could not hold the person.' });
504	    } finally {
505	      this.holding = false;
506	    }
507	  }
508	
509	  /** After a refused stale edit: show the person as the store holds them now, in the row and the form. */
510	  private async showCurrent(sheet: string, id: number): Promise<void> {
511	    const loads = this.session.loads();
512	    try {
513	      const people = await firstValueFrom(
514	        this.http.get<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
515	      );
516	      if (this.session.sheet() !== sheet || this.session.loads() !== loads) return;
517	      this.people.set(people);
518	      const current = people.find((p) => p.id === id);
519	      if (current && this.editing() === id) {
520	        this.name.set(current.name);
521	        this.grade.set(current.grade);
522	      }
523	    } catch {
524	      // the error still shows; re-loading the sheet shows the current values
525	    }
526	  }
527	
528	  /** Show a person as saved: in their place, or added at the end when new. */
529	  protected replace(saved: Person): void {
530	    this.people.update((ps) =>
531	      ps.some((p) => p.id === saved.id) ? ps.map((p) => (p.id === saved.id ? saved : p)) : [...ps, saved],
532	    );
533	  }
534	
535	  /** Show the people again as the store holds them, once a rate changed what they are due. */
536	  protected reloadSheet(): void {
537	    const sheet = this.session.sheet();
538	    if (sheet) void this.reload(sheet);
